HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    try:
        if not url or not isinstance(url, str):
            raise Exception("Invalid URL provided.")

        response = requests.get(url, params=parameters, headers=HEADERS, verify=False)
        response.raise_for_status()

        data = response.json()

        if not data:
            raise Exception("Empty data received from API.")

        if isinstance(data, list):
            df = pd.DataFrame(data)
        elif isinstance(data, dict):
            df = pd.DataFrame([data])
        else:
            raise Exception("Invalid data format received from API.")

        if df.empty:
            raise Exception("DataFrame is empty after conversion.")

        numeric_df = df.select_dtypes(include=['number'])

        if numeric_df.empty or numeric_df.shape[1] < 2:
            raise Exception("Insufficient numerical data for correlation heatmap.")

        import matplotlib.pyplot as plt
        fig, ax = plt.subplots()
        sns.heatmap(numeric_df.corr(), annot=True, cmap='coolwarm', ax=ax)

        return df, ax

    except Exception as e:
        raise Exception(f"Error retrieving or processing data: {e}")

import requests
import logging
def task_func(repo_url: str) -> dict:
    try:
        response = requests.get(repo_url, verify=False, timeout=10)
        response.raise_for_status()
        repo_info = response.json()

        open_issues = repo_info.get('open_issues_count', 0)
